@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#f7f2e7;--muted:#a19a8b;--gold:#e1b458;--orange:#f07844;--bg:#101114;--panel:rgba(17,18,21,.92);--line:rgba(255,255,255,.14);font-family:'DM Sans',sans-serif;color:var(--ink);font-synthesis:none}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;background:#101114;overflow:hidden}
button,select{font:inherit}
button{color:inherit;cursor:pointer}
#game-shell{position:relative;width:100%;height:100%;min-height:520px;overflow:hidden;background:radial-gradient(ellipse at 68% 48%,#705c39 0,#30281e 28%,#121316 68%);isolation:isolate}
#scene{position:absolute;inset:0;width:100%;height:100%;display:block;z-index:-3}
.film-grain,.vignette{position:absolute;inset:0;pointer-events:none;z-index:-1}
.film-grain{opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.4'/%3E%3C/svg%3E")}
.vignette{background:linear-gradient(90deg,rgba(8,9,10,.88),rgba(8,9,10,.36) 43%,rgba(8,9,10,.06) 72%,rgba(8,9,10,.3)),linear-gradient(0deg,rgba(8,9,10,.45),transparent 30%,rgba(8,9,10,.22))}
.screen{position:absolute;inset:0;display:none;animation:fade .35s ease}
.screen.visible{display:block}
from{opacity:0;transform:translateY(7px)}
to{opacity:1;transform:none}
.loading{position:absolute;inset:0;background:#111214;z-index:20;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:14px;transition:opacity .55s}
.loading.done{opacity:0;pointer-events:none}
.crest,.brand-mark{display:grid;place-items:center;width:45px;height:45px;border:1px solid var(--gold);color:var(--gold);font:800 21px 'Barlow Condensed';transform:rotate(45deg)}
.crest{margin-bottom:18px}
.loading-title{font:800 32px 'Barlow Condensed';letter-spacing:.11em}
.loading small{color:#8e8779;font-size:10px;letter-spacing:.17em}
.load-track{width:180px;height:2px;background:#34312b;margin:4px}
.load-track i{display:block;width:60%;height:100%;background:var(--gold);animation:load 1.15s ease-in-out infinite alternate}
from{width:8%}
to{width:100%}
.topbar{height:88px;padding:25px 4.4%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09)}
.brand{display:flex;gap:13px;align-items:center}
.brand-mark{width:38px;height:38px;font-size:17px}
.brand-name{font:800 20px 'Barlow Condensed';letter-spacing:.05em}
.brand-name b{color:var(--gold)}
.brand small{display:block;color:#a49c8d;letter-spacing:.19em;font-size:8px;margin-top:3px}
.top-right{display:flex;align-items:center;gap:26px}
.edition,.platform-note,.menu-footer,.main-character-label,.step-label,.eyebrow,.hud-caption,.round-label,.round-rule,.selection-hint,.detail-kicker,.arena-note,.arena-tag{font-size:9px;letter-spacing:.16em;font-weight:700;color:#b9b1a3}
.icon-btn{background:transparent;border:1px solid var(--line);border-radius:2px;padding:10px 13px;font-size:15px}
.icon-btn span{font-size:9px;letter-spacing:.1em;margin-left:6px}
.hero-copy{position:absolute;left:11.2%;top:24%;z-index:1}
.eyebrow{display:flex;align-items:center;gap:10px;color:var(--gold)}
.eyebrow i{width:18px;height:1px;background:var(--gold)}
h1,h2,p{margin:0}
h1{font:900 clamp(76px,10.4vw,145px)/.79 'Barlow Condensed';letter-spacing:-.035em;margin:24px 0 22px;text-shadow:0 6px 25px rgba(0,0,0,.4)}
h1 em,h2 em{color:var(--gold);font-style:normal}
 .hero-copy p{font-size:14px;line-height:1.75;color:#c5beb2}
.hero-actions{display:flex;gap:12px;margin-top:28px}
.primary-btn,.secondary-btn{border:0;min-height:50px;padding:0 24px;font:800 12px 'Barlow Condensed';letter-spacing:.11em;background:var(--gold);color:#171611;box-shadow:0 8px 28px rgba(0,0,0,.2);transition:.2s}
.primary-btn:hover{background:#f0c86e;transform:translateY(-2px)}
.primary-btn span{font-size:18px;margin-left:27px}
.secondary-btn{background:rgba(17,18,20,.62);color:#ece5d7;border:1px solid rgba(255,255,255,.24)}
.secondary-btn:hover{border-color:var(--gold)}
.secondary-btn span{margin-left:18px;color:var(--gold)}
.platform-note{font-size:8px;margin-top:23px;color:#90897d;letter-spacing:.12em}
.main-character-label{position:absolute;right:6.5%;bottom:21%;text-align:right;color:#e5ddcd}
.label-line{display:inline-block;width:38px;height:1px;background:var(--gold);vertical-align:middle;margin:0 10px 3px 0}
.main-character-label small{display:block;color:#a39a88;font-size:8px;margin-top:9px}
.menu-footer{position:absolute;bottom:0;left:0;right:0;height:52px;padding:0 4.5%;border-top:1px solid rgba(255,255,255,.1);display:flex;justify-content:space-between;align-items:center;font-size:8px;color:#817a70}
.menu-footer b{color:var(--gold);margin:0 8px}
.subhead{height:68px;padding:0 4.3%;border-bottom:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:space-between}
.back-btn,.text-btn{background:none;border:0;color:#bdb5a8;font-size:10px;letter-spacing:.13em;font-weight:700}
.back-btn:hover,.text-btn:hover{color:var(--gold)}
.step-label{color:#dfd7c8}
.step-label span{color:var(--gold);margin:0 9px}
.compact{padding:7px 10px}
.select-heading{display:flex;align-items:flex-end;justify-content:space-between;padding:27px 5% 15px}
.select-heading h2,.arena-heading h2{font:800 44px/.95 'Barlow Condensed';margin-top:9px}
.mode-switch{display:flex;align-items:center;gap:11px;color:#a59e90;font-size:9px;letter-spacing:.15em;font-weight:700}
.mode-switch select{background:#1b1b1b;color:#eee;border:1px solid #444;padding:10px 26px 10px 12px;font-size:11px;min-width:170px}
.character-grid{position:absolute;left:5%;right:5%;top:185px;bottom:112px;display:grid;grid-template-columns:repeat(9,minmax(80px,1fr));gap:9px;align-content:center}
.character-card{position:relative;min-width:0;height:min(35vh,250px);max-height:250px;overflow:hidden;background:linear-gradient(158deg,rgba(170,151,115,.21),rgba(22,23,24,.94) 56%);border:1px solid rgba(255,255,255,.13);padding:0;text-align:left;transition:.2s;isolation:isolate}
.character-card:before{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(9,10,11,.96),transparent 64%);z-index:-1}
.character-card:hover{transform:translateY(-5px);border-color:#b79653}
.character-card.selected{border:1px solid var(--gold);box-shadow:0 0 0 1px rgba(225,180,88,.23),0 0 28px rgba(225,180,88,.13)}
.card-number{position:absolute;top:10px;left:10px;color:#c4ad7e;font:700 12px 'Barlow Condensed'}
.card-glyph{position:absolute;top:13px;right:12px;font:800 13px 'Barlow Condensed';color:rgba(255,255,255,.45)}
.card-figure{position:absolute;width:68%;height:52%;left:16%;top:17%;filter:drop-shadow(0 11px 9px rgba(0,0,0,.45));transition:transform .25s}
.character-card:hover .card-figure,.character-card.selected .card-figure{transform:scale(1.05) translateY(-4px)}
.card-figure svg{width:100%;height:100%;overflow:visible}
.character-card strong{position:absolute;left:11px;right:6px;bottom:39px;font:700 17px/.9 'Barlow Condensed';letter-spacing:.02em}
.character-card small{position:absolute;left:11px;bottom:16px;color:#b2aa9c;font-size:8px;letter-spacing:.06em;white-space:nowrap}
.selection-bottom{position:absolute;left:5%;right:5%;bottom:29px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid rgba(255,255,255,.13);padding-top:17px}
.selection-hint{font-size:8px;color:#a69e90}
.selection-bottom .primary-btn:disabled{opacity:.4;cursor:not-allowed}
.char-detail{display:none}
.char-detail.show{position:absolute;bottom:91px;left:5%;display:flex;align-items:baseline;gap:14px;color:#d9d2c5}
.char-detail strong{font:700 16px 'Barlow Condensed';color:var(--gold)}
.char-detail>span:last-child{font-size:10px;color:#aaa294}
.arena-heading{position:absolute;top:105px;left:9%}
.arena-grid{position:absolute;top:213px;left:9%;right:9%;bottom:115px;display:grid;grid-template-columns:repeat(3,1fr);gap:17px}
.arena-card{position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.2);background:linear-gradient(145deg,#51422d,#191a1d);cursor:pointer;transition:.22s}
.arena-card:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(10,10,11,.93),transparent 70%)}
.arena-card:hover{transform:translateY(-4px)}
.arena-card.selected{border-color:var(--gold);box-shadow:0 0 0 1px var(--gold)}
.arena-art{position:absolute;inset:0;opacity:.72;background:radial-gradient(ellipse at 50% 35%,#d19f4f 0,#655239 19%,transparent 54%),linear-gradient(155deg,#29251e,#84714e 44%,#292524 45%,#151619)}
.arena-card:nth-child(2) .arena-art{filter:hue-rotate(35deg);background:radial-gradient(ellipse at 50% 33%,#e9b65c 0,#826039 17%,transparent 50%),linear-gradient(155deg,#253a3a,#5c7859 44%,#262d29 45%,#151619)}
.arena-card:nth-child(3) .arena-art{filter:hue-rotate(175deg);background:radial-gradient(ellipse at 50% 35%,#daa85d 0,#826037 20%,transparent 52%),linear-gradient(155deg,#1d3046,#4c6a79 44%,#25292e 45%,#151619)}
.arena-card .arena-info{position:absolute;bottom:18px;left:19px;z-index:1}
.arena-info small{color:#d5b87a;font-size:8px;letter-spacing:.17em}
.arena-info strong{display:block;font:800 25px 'Barlow Condensed';margin-top:5px}
.arena-info p{font-size:10px;color:#c6c0b4;margin-top:3px}
.arena-card .arena-tag{position:absolute;right:15px;top:15px;z-index:1;font-size:8px}
.arena-bottom{position:absolute;left:9%;right:9%;bottom:32px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid rgba(255,255,255,.13);padding-top:16px}
.arena-note{font-size:9px}
.fight-ui{display:none;position:absolute;inset:0;pointer-events:none}
.fight-ui.active{display:block}
.fight-top{position:absolute;top:0;left:0;right:0;padding:24px 8%;display:grid;grid-template-columns:1fr 100px 1fr;gap:24px;align-items:center;background:linear-gradient(180deg,rgba(8,9,10,.75),transparent)}
.fighter-hud{position:relative}
.fighter-hud.right{text-align:right}
.hud-name{font:800 23px 'Barlow Condensed';letter-spacing:.06em;text-shadow:0 2px 6px black}
.bar-frame{height:13px;background:rgba(8,8,8,.78);border:1px solid rgba(255,255,255,.46);padding:2px;margin-top:6px;transform:skewX(-11deg)}
.health-bar{height:100%;width:100%;background:linear-gradient(90deg,#d28f3b,#f2d077);transition:width .15s}
.right .health-bar{margin-left:auto;background:linear-gradient(90deg,#e9ba62,#df7851)}
.stamina-frame{height:4px;background:rgba(10,10,10,.72);margin-top:5px}
.stamina-bar{height:100%;background:#74c6a2;width:100%;transition:width .15s}
.hud-caption{font-size:7px;color:#cbc1af;margin-top:6px}
.round-center{text-align:center}
.round-label{font-size:8px}
.round-label b{color:var(--gold)}
.timer{font:800 39px/.95 'Barlow Condensed';margin-top:5px}
.round-rule{font-size:6px;color:#a59b89;margin-top:5px}
.pause-btn{position:absolute;top:27px;right:2.5%;background:rgba(0,0,0,.35);border:1px solid #ffffff44;width:34px;height:34px;pointer-events:auto;font-size:15px}
.fight-toast{position:absolute;top:27%;left:50%;transform:translate(-50%,-50%);font:800 39px 'Barlow Condensed';color:var(--gold);text-shadow:0 3px 16px #000;white-space:nowrap;opacity:0;transition:opacity .25s}
.fight-toast.on{opacity:1}
.mobile-controls{display:none;position:absolute;bottom:20px;left:20px;right:20px;align-items:flex-end;justify-content:space-between;pointer-events:auto}
.move-pad button,.action-pad button{touch-action:none;user-select:none}
.move-pad>button,.move-pad div button{background:rgba(20,21,21,.72);border:1px solid #ffffff44;color:white;width:44px;height:40px;border-radius:7px}
.move-pad div{display:flex;gap:4px;margin-top:4px}
.action-pad{display:grid;grid-template-columns:repeat(3,52px);gap:6px;justify-items:center}
.action-pad .act{border:1px solid #ffffff55;background:rgba(23,23,22,.86);width:50px;height:46px;border-radius:50%;font:700 8px 'Barlow Condensed';letter-spacing:.05em}
.act.punch{background:#a34333}
.act.kick{background:#ba7138}
.act.special{background:#a17a37;grid-column:2}
.act.block{background:#3d6c61}
.act.dodge{background:#456883}
