  for a in j.get('animations',[]):
   if a['name'] in ('Idle','Punch','Kick','MoveForward','MoveBackward','Block','Dodge','Combo','Knockout','GetUp'):
    print(a['name'],[(j['nodes'][c['target']['node']].get('name'),c['target']['path']) for c in a['channels']])
